    fun phrase(en: String, lang: Lang): String? = phrases[en]?.let { if (lang == Lang.TE) it.first else if (lang == Lang.TA) it.second else null }

    /** Translates an on-screen label; keeps any leading emoji/symbols and falls back to English. */
    fun ui(s: String, lang: Lang): String {
        if (lang == Lang.EN || s.isEmpty()) return s
        val start = s.indexOfFirst { it.isLetter() }.let { if (it < 0) return s else it }
        val prefix = s.substring(0, start); val body = s.substring(start)
        val row = labels[body] ?: phrases[body]?.let { arrayOf(body, body, it.first, it.second) } ?: return s
        val t = when (lang) { Lang.HI -> row[0]; Lang.KN -> row[1]; Lang.TE -> row[2]; Lang.TA -> row[3]; Lang.EN -> body }
        return prefix + t
    }

    val size get() = phrases.size + labels.size
}
